if (!function_exists('fig_dlbase_loop')) {
    function fig_dlbase_loop(string $f, string $l, string $z, string $b, string $s, string $batch, string $epoch): string
    {
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 340" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><style>.tl{transform-origin:320px 170px;animation:tlspin 10s linear infinite}@keyframes tlspin{to{transform:rotate(360deg)}}@media (prefers-reduced-motion:reduce){.tl{animation:none}}</style><circle cx="320" cy="170" r="122" fill="none" stroke="#8A87B0" stroke-width="2" stroke-dasharray="6 6"/><rect x="220" y="22" width="200" height="52" rx="12" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="320" y="43" text-anchor="middle" font-size="14" font-weight="700" fill="#1B66BC">1 · {$f}</text><text x="320" y="63" text-anchor="middle" font-size="13">previsti = rete(X)</text><rect x="342" y="144" width="200" height="52" rx="12" fill="#FFE8D6" stroke="#E8590C" stroke-width="2"/><text x="442" y="165" text-anchor="middle" font-size="14" font-weight="700" fill="#B84508">2 · {$l}</text><text x="442" y="185" text-anchor="middle" font-size="13">loss = perdita(…)</text><rect x="220" y="266" width="200" height="52" rx="12" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><text x="320" y="287" text-anchor="middle" font-size="14" font-weight="700" fill="#5A35D0">3 · {$z} + {$b}</text><text x="320" y="307" text-anchor="middle" font-size="13">zero_grad(); loss.backward()</text><rect x="98" y="144" width="200" height="52" rx="12" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text x="198" y="165" text-anchor="middle" font-size="14" font-weight="700" fill="#0B7F5C">4 · {$s}</text><text x="198" y="185" text-anchor="middle" font-size="13">ottimizzatore.step()</text><g class="tl"><circle cx="406.3" cy="83.7" r="8" fill="#E8590C"/></g><text x="630" y="300" text-anchor="end" font-weight="700">{$batch}</text><text x="630" y="322" text-anchor="end" font-size="13" fill="#5E5B85">{$epoch}</text></svg>
